# aplicar-v70-suporte-admin-e-superadmin.ps1
# Atualiza o suporte:
#
# ADMIN:
# - pode acessar /admin/support
# - ve somente suportes criados por ele, atrelados aos seus eventos
# - pode criar suporte relatando problema para o SUPER_ADMIN
#
# SUPER_ADMIN:
# - continua vendo a central completa
# - Suporte normal mostra chamados dos admins
# - Suporte impulsionamentos mostra impulsionamentos pagos
# - Suporte aprovacao de admins aprova customer/operator -> admin
#
# O script cria API + tabela AdminSupportTicket.

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

function Write-TextBase64File($RelativePath, $Base64Content) {
  $Target = Join-Path $Root $RelativePath
  $TargetDir = Split-Path $Target -Parent

  if (-not (Test-Path $TargetDir)) {
    New-Item -ItemType Directory -Path $TargetDir -Force | Out-Null
  }

  if (Test-Path $Target) {
    $Backup = "$Target.bak-v70-$Stamp"
    Copy-Item $Target $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray
  }

  $Content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
  Set-Content -Path $Target -Value $Content -Encoding UTF8
  Write-Host "Atualizado: $RelativePath" -ForegroundColor Green
}

function Add-SupportTicketModelToPrisma() {
  $SchemaPath = Join-Path $Root "apps\api\prisma\schema.prisma"

  if (-not (Test-Path $SchemaPath)) {
    throw "schema.prisma nao encontrado."
  }

  $Schema = Get-Content $SchemaPath -Raw

  if ($Schema -match "model\s+AdminSupportTicket\s+\{") {
    Write-Host "Modelo AdminSupportTicket ja existe no Prisma." -ForegroundColor Yellow
    return
  }

  $Backup = "$SchemaPath.bak-v70-$Stamp"
  Copy-Item $SchemaPath $Backup -Force
  Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray

  $Model = @'

model AdminSupportTicket {
  id       String @id @default(uuid())
  protocol String @unique

  requesterUserId String
  requesterRole   String?
  requesterName   String?
  requesterEmail  String?
  requesterCpf    String?

  eventId    String?
  eventTitle String

  subject  String
  message  String
  priority String @default("NORMAL")
  category String @default("EVENT_SUPPORT")
  status   String @default("OPEN")

  replyText      String?
  repliedAt      DateTime?
  moderatorUserId String?
  moderatorName   String?
  moderatorEmail  String?

  submittedAt DateTime @default(now())
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@index([requesterUserId])
  @@index([requesterEmail])
  @@index([eventId])
  @@index([status])
}

'@

  Add-Content -Path $SchemaPath -Value $Model -Encoding UTF8
  Write-Host "Modelo AdminSupportTicket adicionado ao schema.prisma." -ForegroundColor Green
}

function Patch-AppModule() {
  $AppModulePath = Join-Path $Root "apps\api\src\app.module.ts"

  if (-not (Test-Path $AppModulePath)) {
    throw "app.module.ts nao encontrado."
  }

  $Content = Get-Content $AppModulePath -Raw

  if ($Content -match "AdminSupportTicketsModule") {
    Write-Host "AdminSupportTicketsModule ja existe no app.module.ts." -ForegroundColor Yellow
    return
  }

  $Backup = "$AppModulePath.bak-v70-$Stamp"
  Copy-Item $AppModulePath $Backup -Force
  Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray

  $ImportLine = "import { AdminSupportTicketsModule } from './admin-support-tickets/admin-support-tickets.module';"
  $LastImportMatch = [regex]::Matches($Content, "import\s+.*?;\s*") | Select-Object -Last 1

  if ($null -eq $LastImportMatch) {
    $Content = $ImportLine + "`r`n" + $Content
  } else {
    $InsertAt = $LastImportMatch.Index + $LastImportMatch.Length
    $Content = $Content.Insert($InsertAt, "`r`n$ImportLine")
  }

  if ($Content -match "imports\s*:\s*\[") {
    $Content = [regex]::Replace(
      $Content,
      "imports\s*:\s*\[",
      "imports: [`r`n    AdminSupportTicketsModule,",
      1
    )
  } else {
    throw "Nao encontrei imports: [ no app.module.ts"
  }

  Set-Content -Path $AppModulePath -Value $Content -Encoding UTF8
  Write-Host "AdminSupportTicketsModule adicionado ao app.module.ts." -ForegroundColor Green
}

function Patch-HeaderSupportMenu() {
  $HeaderPath = Join-Path $Root "apps\web\src\components\customer\CustomerHeader.tsx"

  if (-not (Test-Path $HeaderPath)) {
    Write-Host "Aviso: CustomerHeader.tsx nao encontrado." -ForegroundColor Yellow
    return
  }

  $Content = Get-Content $HeaderPath -Raw
  $Original = $Content

  $Content = $Content.Replace('/admin/support?tab=admin-requests', '/admin/support')
  $Content = $Content.Replace('/admin/support/admin-requests', '/admin/support')

  # Remove nomes antigos que nao devem aparecer separados.
  $Lines = $Content -split "`r?`n"
  $Filtered = New-Object System.Collections.Generic.List[string]

  foreach ($Line in $Lines) {
    if ($Line -match 'Solicitaç|Solicitac|Atendimentos') {
      continue
    }

    $Filtered.Add($Line)
  }

  $Content = ($Filtered -join "`r`n")

  if ($Content -notmatch 'label:\s*"Suporte"\s*,\s*href:\s*"/admin/support"') {
    $Content = $Content.Replace(
      '{ label: "Pedidos", href: "/admin/orders" },',
      '{ label: "Pedidos", href: "/admin/orders" },' + "`r`n" + '    { label: "Suporte", href: "/admin/support" },'
    )
  }

  if ($Content -ne $Original) {
    $Backup = "$HeaderPath.bak-v70-$Stamp"
    Copy-Item $HeaderPath $Backup -Force
    Set-Content -Path $HeaderPath -Value $Content -Encoding UTF8
    Write-Host "Header ajustado: suporte unico em /admin/support." -ForegroundColor Green
  } else {
    Write-Host "Header sem alteracoes." -ForegroundColor Yellow
  }
}

function Stop-NodeForPrisma() {
  Write-Host "Parando processos node.exe para evitar EPERM no Prisma..." -ForegroundColor Yellow
  Get-Process node -ErrorAction SilentlyContinue | ForEach-Object {
    try {
      Stop-Process -Id $_.Id -Force -ErrorAction Stop
    } catch {
      Write-Host "Nao consegui parar node PID $($_.Id)." -ForegroundColor Yellow
    }
  }
  Start-Sleep -Seconds 2
}

function Run-Prisma() {
  $ApiPath = Join-Path $Root "apps\api"

  if (-not (Test-Path $ApiPath)) {
    throw "Pasta apps\api nao encontrada."
  }

  Stop-NodeForPrisma

  Push-Location $ApiPath

  try {
    Write-Host "Rodando: npx prisma db push" -ForegroundColor Cyan
    npx prisma db push

    if ($LASTEXITCODE -ne 0) {
      throw "npx prisma db push falhou."
    }

    Write-Host "Rodando: npx prisma generate" -ForegroundColor Cyan
    npx prisma generate

    if ($LASTEXITCODE -ne 0) {
      throw "npx prisma generate falhou."
    }
  }
  finally {
    Pop-Location
  }
}

Write-Host "Aplicando v70 - suporte admin e super admin..." -ForegroundColor Cyan

Write-TextBase64File "apps\api\src\admin-support-tickets\dto\create-admin-support-ticket.dto.ts" ""
Write-TextBase64File "apps\api\src\admin-support-tickets\dto\review-admin-support-ticket.dto.ts" ""
Write-TextBase64File "apps\api\src\admin-support-tickets\admin-support-tickets.module.ts" ""
Write-TextBase64File "apps\api\src\admin-support-tickets\admin-support-tickets.controller.ts" ""
Write-TextBase64File "apps\api\src\admin-support-tickets\admin-support-tickets.service.ts" ""
Write-TextBase64File "apps\web\src\app\admin\support\page.tsx" ""

Add-SupportTicketModelToPrisma
Patch-AppModule
Patch-HeaderSupportMenu
Run-Prisma

Write-Host ""
Write-Host "v70 aplicada com sucesso." -ForegroundColor Green
Write-Host ""
Write-Host "Como fica:" -ForegroundColor Cyan
Write-Host "- ADMIN em /admin/support: ve apenas seus suportes e pode criar suporte para o super admin." -ForegroundColor Cyan
Write-Host "- SUPER_ADMIN em /admin/support: ve suporte normal, impulsionamentos e aprovacao de admins." -ForegroundColor Cyan
Write-Host ""
Write-Host "Agora reinicie API e WEB:" -ForegroundColor Cyan
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\api"' -ForegroundColor Cyan
Write-Host "npm run start:dev" -ForegroundColor Cyan
Write-Host ""
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\web"' -ForegroundColor Cyan
Write-Host "npm run dev" -ForegroundColor Cyan
